import random
random.seed(4242)
last_seen = {n: 0 for n in range(1, 51)}
for draw in range(1, 101):
    for n in random.sample(range(1, 51), 5):
        last_seen[n] = draw
gaps = sorted(((100 - last_seen[n], n) for n in range(1, 51)), reverse=True)
print("SIMULATED set: 100 draws")
print("longest absences at end of set (descriptive only):")
for gap, n in gaps[:5]:
    print(f"number {n}: {gap} draws since last appearance")
print("next-draw chance per main number: still 5 in 50")
